_CACHE = {}


def get_skater_mesh_pydata():
    """Returns (verts_list, faces_list) for the exact 1.81217 m in-game Skater 3D mesh in Blender Z-up coordinates."""
    if "skater" not in _CACHE:
        v_raw = zlib.decompress(base64.b85decode(_SKATER_VERTS_B85))
        f_raw = zlib.decompress(base64.b85decode(_SKATER_FACES_B85))
        verts = [struct.unpack_from("<3f", v_raw, i * 12) for i in range(SKATER_VERTS_COUNT)]
        faces = [struct.unpack_from("<3H", f_raw, i * 6) for i in range(SKATEBOARD_FACES_COUNT if False else SKATER_FACES_COUNT)]
        _CACHE["skater"] = (verts, faces)
    return _CACHE["skater"]


def get_skateboard_mesh_pydata():
    """Returns (verts_list, faces_list) for the exact 0.82454 m x 0.21701 m x 0.14272 m in-game Skateboard 3D mesh in Blender Z-up coordinates."""
    if "skateboard" not in _CACHE:
        v_raw = zlib.decompress(base64.b85decode(_SKATEBOARD_VERTS_B85))
        f_raw = zlib.decompress(base64.b85decode(_SKATEBOARD_FACES_B85))
        verts = [struct.unpack_from("<3f", v_raw, i * 12) for i in range(SKATEBOARD_VERTS_COUNT)]
        faces = [struct.unpack_from("<3H", f_raw, i * 6) for i in range(SKATEBOARD_FACES_COUNT)]
        _CACHE["skateboard"] = (verts, faces)
    return _CACHE["skateboard"]
